abstract class SecureCacheKeys {
  static const String accessToken = 'accessToken';
  static const String refreshToken = 'refreshToken';
  static const String userId = 'userId';
  static const String userRole = 'userRole';
  static const String userName = 'userName';
  static const String userEmail = 'userEmail';
  static const String userPhone = 'userPhone';
  static const String registrationMode = 'registrationMode';
  static const String registrationModes = 'registrationModes';
  static const String savedAccounts = 'savedAccounts';

  static const sessionKeys = [
    accessToken,
    refreshToken,
    userId,
    userRole,
    userName,
    userEmail,
    userPhone,
    registrationMode,
    registrationModes,
  ];
}
